mapper.insert:
INSERT INTO data_quality_rule (
    target_table, target_column, rule_type, threshold,
    range_min, range_max, severity, status, schedule_cron, description
) VALUES (
    #{targetTable}, #{targetColumn}, #{ruleType}, #{threshold},
    #{rangeMin}, #{rangeMax},
    COALESCE(#{severity},'WARN'), COALESCE(#{status},'ACTIVE'),
    COALESCE(#{scheduleCron},'0 0 6 * * *'),
    #{description}
)

mapper.select:
SELECT * FROM data_quality_rule

    AND target_table = #{p.targetTable}
    AND rule_type    = #{p.ruleType}
    AND status       = #{p.status}

ORDER BY id

SELECT r.* FROM data_quality_report r
JOIN data_quality_rule q ON q.id = r.rule_id

    AND r.rule_id   = #{p.ruleId}
    AND r.violation = #{p.violation}
    AND q.severity  = #{p.severity}

ORDER BY r.checked_at DESC
LIMIT #{p.size} OFFSET #{p.offset}

SELECT COUNT(*) FROM data_quality_report r
JOIN data_quality_rule q ON q.id = r.rule_id

    AND r.rule_id   = #{p.ruleId}
    AND r.violation = #{p.violation}
    AND q.severity  = #{p.severity}
